def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))
    day = day_context.get('day', 0)

    # Identify alive opponents and collect yesterday bids (immediate reaction only)
    alive_opponents = [o for o in opponents_status.values() if o.get('alive', False)]
    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {}) or {}
        if prev and prev.get('bid') is not None:
            try:
                yesterday_bids.append(float(prev.get('bid')))
            except Exception:
                pass

    # Base bid target depends on supply: low supply -> more aggressive to avoid no-water days
    # Since supply is only 15-25, if supply is near WATER_REQ we should bid higher.
    if supply <= WATER_REQ + 0.5:
        base = DAILY_SALARY * 0.75
    elif supply <= WATER_REQ + 3.0:
        base = DAILY_SALARY * 0.6
    else:
        base = DAILY_SALARY * 0.5

    # React to opponent pressure from yesterday
    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)
        # If someone was bidding extremely high, they likely needed water badly; match partially.
        if highest_prev_bid >= DAILY_SALARY * 0.85:
            if my_status.get('hp', 0) is not None and my_status['hp'] <= 2:
                bid = DAILY_SALARY * 0.95
            else:
                bid = max(base, DAILY_SALARY * 0.7)
        elif highest_prev_bid >= DAILY_SALARY * 0.6:
            # Moderate competition: slight increase over base
            bid = max(base, highest_prev_bid * 0.75)
        else:
            bid = base
    else:
        bid = base

    # If we are already in danger (low hp or many no-water days), increase bid.
    hp = float(my_status.get('hp', 0.0))
    no_water_days = int(my_status.get('no_water_days', 0))
    budget = float(my_status.get('budget', 0.0))

    if hp <= 2 or no_water_days >= 2:
        bid = max(bid, DAILY_SALARY * 0.9)
    elif hp <= 4 or no_water_days >= 1:
        bid = max(bid, DAILY_SALARY * 0.7)

    # Never exceed budget
    if budget <= 0:
        return 0

    # Also cap bid to avoid overspending: keep some runway for later days
    # Budget fraction depends on remaining hp.
    if hp >= 8:
        max_frac = 0.55
    elif hp >= 5:
        max_frac = 0.65
    else:
        max_frac = 0.8

    cap = budget * max_frac
    final_bid = min(bid, cap, budget)

    # Ensure bid is non-negative
    if final_bid < 0:
        final_bid = 0

    return float(final_bid)

