        pressure += 0.42
    elif highest_prev >= 80:
        pressure += 0.32
    elif highest_prev >= 65:
        pressure += 0.2
    elif highest_prev >= 40:
        pressure += 0.1

    pressure += min(0.2, rich_threats * 0.06 + urgent_threats * 0.05)
    pressure += tightness * 0.28

    score = desperation + pressure

    if hp <= 2 or no_water >= 2:
        bid = max(88.0, highest_prev + 1.0)
    elif supply <= 16:
        bid = max(74.0, highest_prev + 1.5, avg_prev + 4.0)
    elif score >= 0.75:
        bid = max(68.0, highest_prev + 1.0)
    elif score >= 0.5:
        bid = max(52.0, avg_prev + 2.0, highest_prev * 0.82)
    else:
        bid = 24.0 + tightness * 10.0
        if highest_prev < 35:
            bid = max(bid, highest_prev + 1.0)

    if budget < DAILY_SALARY * 1.2:
        bid = min(bid, budget * 0.72)
    elif budget < DAILY_SALARY * 2:
        bid = min(bid, budget * 0.82)

